// Product list used by the site: the catalogue data plus images and product sheets.
// Catalogue wording lives in products.catalogue.js; images come from productImages.js and sheets from productSheets.js
// (both generated by sync-mockups.mjs).
import { PRODUCTS as CATALOGUE, CATEGORIES, SAMPLE_POT, SAMPLE_BUNDLE } from "./products.catalogue.js";
import { PRODUCT_IMAGES } from "./productImages.js";
import { PRODUCT_SHEETS } from "./productSheets.js";

export { CATEGORIES, SAMPLE_POT, SAMPLE_BUNDLE };

export const PRODUCTS = CATALOGUE.map(p => {
  const im = PRODUCT_IMAGES[p.id];
  return {
    ...p,
    img: im ? im.main : null,
    imgBySize: im ? im.bySize : {},
    gallery: im ? im.gallery : [],
    sheet: PRODUCT_SHEETS.includes(p.id) ? "/datasheets/" + p.id + ".pdf" : null,
  };
});

// slug -> { category, sub } for the category pages (#/decorative-paints, #/decorative-paints-interior, ...)
export const CATEGORY_PAGES = {};
for (const [id, cat] of Object.entries(CATEGORIES)) {
  CATEGORY_PAGES[cat.slug] = { category: id, sub: null };
  for (const sub of cat.subcategories) CATEGORY_PAGES[cat.slug + "-" + sub.id] = { category: id, sub: sub.id };
}
